from datetime import date
from typing import Optional

from fastapi import APIRouter, HTTPException, Query

from app.services.recommendation_service import recommendation_service

router = APIRouter(prefix="/api/recommendations", tags=["recommendations"])


@router.get("")
def list_recommendations(
    start_date: Optional[date] = Query(None, description="Start date (default: 30 days ago)"),
    end_date: Optional[date] = Query(None, description="End date (default: today)"),
):
    """List all recommendations generated by the recommendation engine."""
    recommendations = recommendation_service.generate_recommendations(start_date, end_date)
    return {
        "recommendations": recommendations,
        "total": len(recommendations),
    }


@router.get("/{recommendation_id}")
def get_recommendation(recommendation_id: str):
    """Get detailed information about a specific recommendation."""
    result = recommendation_service.get_recommendation(recommendation_id)
    if result is None:
        raise HTTPException(status_code=404, detail=f"Recommendation '{recommendation_id}' not found")
    return result
